function startQuiz(mode="adaptive"){
 const weak=new Set(adaptiveStats().filter(v=>v.priority>0).map(v=>v.lesson.id)),history=state.quizHistory||[],last=new Set(history[0]||[]),counts=new Map();
 history.flat().forEach(k=>counts.set(k,(counts.get(k)||0)+1));
 const pool=shuffleAdaptive(lessons.flatMap(l=>buildLessonQuestions(l,lessonExtras[l.day-1]).slice(0,4).map(q=>({...q,title:l.title,key:l.id+"|"+q.question,targeted:mode!=="random"&&weak.has(l.id)}))));
 const rank=(a,b)=>Number(last.has(a.key))-Number(last.has(b.key))||(counts.get(a.key)||0)-(counts.get(b.key)||0);
 const chosen=[],questions=new Set(),usedLessons=new Set();
 const add=q=>{if(chosen.length>=10||questions.has(q.question)||usedLessons.has(q.title))return;questions.add(q.question);usedLessons.add(q.title);chosen.push(q)};
 if(mode!=="random")for(const q of pool.filter(q=>q.targeted&&!last.has(q.key)).sort(rank)){if(chosen.length>=6)break;add(q)}
 for(const q of pool.sort(rank))add(q);
 quiz=shuffleAdaptive(chosen).map(q=>{const correct=q.options[q.answer],options=shuffleAdaptive(q.options);return {...q,options,answer:options.indexOf(correct)}});
 adaptiveCount=quiz.filter(q=>q.targeted).length;quizIndex=0;quizScore=0;quizAnswers=[];quizStarted=Date.now();renderQuestion()
}
function renderQuestion(){const q=quiz[quizIndex];if(!q){const pct=Math.round(quizScore/quiz.length*100),seconds=Math.round((Date.now()-quizStarted)/1000);state.best=Math.max(state.best,quizScore);state.quizHistory=[quiz.map(q=>q.key),...(state.quizHistory||[])].slice(0,30);record("Quiz",adaptiveCount?"Quiz adaptatif":"Quiz A2–B1",seconds,pct,{answers:quizAnswers,targeted:adaptiveCount});document.getElementById("quizArea").innerHTML="<div class='quiz-card result-card'><h2>Quiz terminé</h2><div class='result-score'>"+quizScore+"/10</div><p>"+adaptiveCount+" questions ciblées sur tes difficultés</p><p>Temps réel : "+fmtTime(seconds)+" · "+pct+"%</p><button class='primary full' onclick='startQuiz()'>Nouveau quiz</button><button class='secondary full' onclick='startQuiz(\"random\")'>Quiz aléatoire</button><button class='secondary full' onclick=\"showScreen('progress')\">Voir mon bilan</button></div>";return}document.getElementById("quizArea").innerHTML="<div class='quiz-card'><div class='row between'><b>Question "+(quizIndex+1)+"/10</b><span class='pill'>"+quizScore+" bonne(s) réponse(s)</span></div><div class='q-progress'><i style='width:"+((quizIndex+1)*10)+"%'></i></div><p class='muted'>"+(q.targeted?"Révision ciblée":"Entraînement")+" · "+esc(q.title)+"</p><p class='question'>"+esc(q.question)+"</p><div class='answers'>"+q.options.map((x,i)=>"<button class='answer' onclick='answerQuiz("+i+")'>"+x+"</button>").join("")+"</div><div id='quizFeedback' class='feedback'></div><button id='nextQuestion' class='primary full' style='display:none' onclick='nextQuestion()'>Continuer</button></div>"}
function answerQuiz(i){if(document.getElementById('nextQuestion').style.display!=='none')return;const q=quiz[quizIndex],ok=i===q.answer;if(ok)quizScore++;quizAnswers.push({lesson:q.title,question:q.question,selected:q.options[i],answer:q.options[q.answer],correct:ok});state.attempts.unshift({date:dayKey(),lesson:q.title,question:q.question,correct:ok,selected:q.options[i],answer:q.options[q.answer]});document.querySelectorAll("#quizArea .answer").forEach((b,j)=>{b.disabled=true;if(j===q.answer)b.classList.add("correct");else if(j===i)b.classList.add("wrong")});set("quizFeedback",ok?"Bonne réponse !":"Réponse : "+q.options[q.answer]+". "+q.explanation);document.getElementById("quizFeedback").className="feedback "+(ok?"good":"bad");document.getElementById("nextQuestion").style.display="block";save()}
