function allCards(){const raw=flashcards.concat(topics.flatMap((week,w)=>week.flatMap((_,d)=>vocab[(w+d)%vocab.length])),lessons.flatMap(l=>l.words),lessonExtras.map(x=>x[2].split("|")),extraVocabulary());const seen=new Set();return raw.filter(c=>{const k=c[0].toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).map((c,i)=>({id:"v"+i,front:c[0],back:c[1]})).filter(c=>c.front&&c.back)}
function availableCards(){return allCards().filter(c=>!state.knownCards.includes(c.id))}
function renderCard(advance=false){const list=availableCards();const previous=currentCard?.id;if(!list.length){currentCard=null;document.querySelectorAll(".flash-wrap .row button").forEach(b=>b.disabled=true);set("flashCount","Toutes les fiches de cette série sont connues");set("flashFront","Bravo !");set("flashBack","De nouvelles fiches seront ajoutées.");document.getElementById("markCard").style.display="none";return}document.querySelectorAll(".flash-wrap .row button").forEach(b=>b.disabled=false);const index=list.findIndex(c=>c.id===previous);currentCard=list[advance?(index+1)%list.length:Math.max(0,index)];cardStarted=Date.now();flipped=false;document.getElementById("markCard").style.display="block";set("flashCount",list.length+" fiches à découvrir · "+state.knownCards.length+" connues");set("flashFront",currentCard.front);set("flashBack","");document.getElementById("flashcard").classList.remove("flipped");document.querySelector(".flash-label").textContent="ESPAGNOL";document.querySelector(".flash-hint").textContent="Toucher pour retourner"}
