function gradeReview(ok){const c=dueCards().find(c=>c.id===window.marabouReviewId);if(!c)return;scheduleReview(c.id,ok);record("Révision",c.front,Math.round((Date.now()-window.marabouReviewStart)/1000),ok?100:0,{cardId:c.id});renderReview()}
function renderAdaptiveDashboard(){const due=dueCards().length,next=lessons.find(l=>!state.done.includes(l.id)),weak=adaptiveStats().filter(v=>v.priority>0),el=document.getElementById("dailyAdvice");if(el){const today=state.daily[dayKey()]||0;el.innerHTML='<p class="muted">'+(today>=900?'Objectif quotidien atteint.':'Il te reste environ '+Math.ceil((900-today)/60)+' min pour ton objectif.')+'</p>'+(due?'<button class="secondary full" onclick="openReview()">Réviser '+due+' fiche(s)</button>':'')+(weak.length?'<p>Priorité : '+esc(weak[0].lesson.title)+'</p><button class="secondary full" onclick="showScreen(\'practice\')">Quiz ciblé</button>':'')+(next?'<button class="primary full" onclick="openLesson('+(next.day-1)+')">Jour '+next.day+' · '+esc(next.title)+'</button>':'<p>Parcours terminé.</p>')}
const level=document.getElementById("dynamicLevel");if(level){const recent=state.attempts.filter(a=>typeof a.correct==="boolean").slice(0,100),score=recent.length?Math.round(100*recent.filter(a=>a.correct).length/recent.length):0,b1=recent.filter(a=>lessons.find(l=>l.title===a.lesson)?.week>=9),b1score=b1.length?b1.filter(a=>a.correct).length/b1.length:0;const label=recent.length<20?"Données insuffisantes":state.done.length>=56&&b1.length>=20&&b1score>=.8&&score>=80?"B1 en consolidation":state.done.length>=28&&score>=70?"A2+ en progression":"A2 en consolidation";level.innerHTML='<h2>'+label+'</h2><p class="muted">'+recent.length+' réponses récentes · '+(recent.length?score+' % de réussite':'aucun score')+' · '+state.done.length+'/84 leçons</p><p class="muted">Indicateur interne, pas une certification CECRL ; oral et expression libre non évalués.</p>'}
set("reviewDue",due+" fiche(s) à réviser");}
